FILE = "joshua-baraka-hipipo-artist-of-the-year-2026.html"
TITLE = "Joshua Baraka is HiPipo's Artist of the Year, again"
TAG = "The Wrap"
H1 = "Joshua Baraka is HiPipo’s Artist of the Year, again"
DEK = "The Ugandan singer won four awards at the 15th HiPipo Music Awards in Kampala, in the same week he released his EP Recess II."
META = "The Wrap · Continental · 15 Nov 2026 · 3 min read"
LEAD = ("img/wr-joshua-baraka-hipipo-2026.jpg", "Joshua Baraka (centre) with his award at the 2026 HiPipo Music Awards", "@itsjoshuabaraka / Instagram")

BODY = [
("p", "Joshua Baraka has been named Artist of the Year at the HiPipo Music Awards for the second year running. He took the top prize at the 15th edition of the awards, held at Kampala Serena Hotel on Friday 13 November 2026."),
("p", "He left with four awards in total. One of them was East Africa Best Act/Song for “This Time”, his song with the producer JAE5. HiPipo has not yet published its full list of 2026 winners, and we will add Baraka’s other two categories once it does."),
("p", "HiPipo winners are decided by public vote. Sharing the news on Instagram, Baraka thanked “Natives”, as he addresses his fans, for voting."),
("h2", "The record", "Three years ", "in a row"),
("p", "Baraka has now won at HiPipo three years running. In 2024 he took East Africa Best Artist and East Africa Best Act/Song for “Dalilah”. In 2025 he won four: Africa’s Number One, East Africa Best Artist, Best Male Artist and Artist of the Year."),
("h2", "The week", "A release ", "weekend"),
("p", "The awards came days after he released his new EP, <em>Recess II</em>, which arrived on 12 November. In the same Instagram post, he called it “an eventful weekend.”"),
("p", "His next big date is at home. B’rakaland EA, his headline show, is at Lugogo Hockey Grounds in Kampala on 28 November 2026. Earlier this month, Visa named him its first Ugandan brand ambassador (<a href=\"joshua-baraka-visa-ambassador.html\">read our story</a>)."),
("h2", "Also on the night", "A heritage ", "award"),
("p", "The Ugandan-born, UK-based duo Ganda Boys received the African Heritage Award for their work promoting Ugandan and African culture through music. Justine Nameere, Minister of State for Local Government, presented it on behalf of Vice President Jessica Alupo."),
]

